UPDATE
  TB_CODE_DATA
SET
    CODE_GRP = #{codeGrp}
   ,CODE_NM = #{codeNm}
   ,CODE_ENG_NM = #{codeEngNm}
   ,CODE_VAL = #{codeVal}
   ,CODE_VAL_DESC = #{codeValDesc, jdbcType=VARCHAR}
   ,PARENT_CODE_VAL = NULLIF(#{parentCodeVal, jdbcType=VARCHAR}, '')
   ,UPDT_DT = to_char(now(), 'YYYYMMDDHH24MISS')
   ,UPDT_USER_ID  = #{updtUserId, jdbcType=VARCHAR}
WHERE
  CODE_ID = #{id}
